import { jest } from '@jest/globals';

// IMPORTANT: Mock prisma BEFORE importing any code that uses it
jest.mock('../../../src/prisma', () => {
  return jest.requireActual('../../mocks/database.mock');
});

import { runProgressCheck } from '../../../src/jobs/progressCheck';
import { prisma } from '../../../src/prisma';
import type { UnitPlan, LessonPlan, User } from '@teaching-engine/database';

// Create proper TypeScript interfaces for test data
interface TestLessonPlan {
  id: number;
  date: Date;
  title?: string;
  unitPlanId?: string;
}

interface TestUnitPlan {
  id: string;
  title: string;
  endDate: Date;
  lessonPlans: TestLessonPlan[];
  user: { id: number; name: string };
  userId?: number;
  startDate?: Date;
  createdAt?: Date;
  updatedAt?: Date;
}

// Mock console.warn to verify notifications
const mockWarn = jest.spyOn(console, 'warn').mockImplementation(() => {});

// Verify mock is set up correctly
describe('Mock Setup Verification', () => {
  it('should have mocked prisma correctly', () => {
    expect(prisma).toBeDefined();
    expect((prisma as any).unitPlan).toBeDefined();
    expect((prisma as any).unitPlan.findMany).toBeDefined();
    expect(jest.isMockFunction((prisma as any).unitPlan.findMany)).toBe(true);
  });
  
  it('should return array from findMany mock', async () => {
    const mockPrisma = prisma as any;
    mockPrisma.unitPlan.findMany.mockResolvedValue([{ id: 'test', title: 'Test' }]);
    
    const result = await mockPrisma.unitPlan.findMany();
    expect(Array.isArray(result)).toBe(true);
    expect(result).toHaveLength(1);
  });
});

describe('Progress Check Job', () => {
  beforeEach(() => {
    jest.clearAllMocks();
    
    // Get the mock prisma instance
    const mockPrisma = prisma as any;
    
    // Debug: Check if unitPlan exists
    if (!mockPrisma.unitPlan) {
      console.error('ERROR: prisma.unitPlan is undefined. prisma keys:', Object.keys(mockPrisma));
      throw new Error('Mock setup failed: unitPlan model not found on prisma mock');
    }
    
    // Reset the unitPlan mock data
    if (mockPrisma.unitPlan._reset) {
      mockPrisma.unitPlan._reset();
    }
    
    // Ensure findMany is properly mocked with empty array default
    if (!mockPrisma.unitPlan.findMany) {
      console.error('ERROR: unitPlan.findMany is undefined');
      throw new Error('Mock setup failed: findMany method not found on unitPlan');
    }
    
    // Reset and configure the mock
    mockPrisma.unitPlan.findMany.mockReset();
    mockPrisma.unitPlan.findMany.mockResolvedValue([]);
  });

  afterAll(() => {
    mockWarn.mockRestore();
  });

  describe('runProgressCheck', () => {
    it('should check unit plans ending within a week', async () => {
      const today = new Date();
      const nextWeek = new Date();
      nextWeek.setDate(today.getDate() + 7);

      const mockPrisma = prisma as any;
      
      // Debug: check what findMany returns
      console.log('Mock findMany function:', typeof mockPrisma.unitPlan.findMany);
      console.log('Is mock function?', jest.isMockFunction(mockPrisma.unitPlan.findMany));
      
      // Ensure the mock returns an array
      mockPrisma.unitPlan.findMany.mockResolvedValue([]);

      await runProgressCheck();

      expect(mockPrisma.unitPlan.findMany).toHaveBeenCalledWith({
        where: {
          endDate: { lte: expect.any(Date) },
        },
        include: { lessonPlans: true, user: true },
      });

      const callArgs = mockPrisma.unitPlan.findMany.mock.calls[0][0];
      const queryDate = callArgs.where.endDate.lte;
      
      // Verify the query date is approximately one week from now
      const timeDiff = Math.abs(queryDate.getTime() - nextWeek.getTime());
      expect(timeDiff).toBeLessThan(1000); // Within 1 second
    });

    it('should warn about unit plans with upcoming lessons', async () => {
      const today = new Date();
      const futureDate = new Date(today.getTime() + 86400000); // Tomorrow

      const mockUnitPlans: TestUnitPlan[] = [
        {
          id: 'unit-plan-a',
          title: 'Unit Plan A',
          endDate: futureDate,
          startDate: today,
          userId: 1,
          createdAt: new Date(),
          updatedAt: new Date(),
          lessonPlans: [
            { id: 1, date: futureDate, title: 'Future Lesson', unitPlanId: 'unit-plan-a' }, // Future lesson
            { id: 2, date: new Date(today.getTime() - 86400000), title: 'Past Lesson', unitPlanId: 'unit-plan-a' }, // Past lesson
          ],
          user: { id: 1, name: 'Teacher 1' },
        },
        {
          id: 'unit-plan-b',
          title: 'Unit Plan B',
          endDate: futureDate,
          startDate: today,
          userId: 2,
          createdAt: new Date(),
          updatedAt: new Date(),
          lessonPlans: [
            { id: 3, date: new Date(today.getTime() - 86400000), title: 'Past Lesson Only', unitPlanId: 'unit-plan-b' }, // Past lesson only
          ],
          user: { id: 2, name: 'Teacher 2' },
        },
      ];

      const mockPrisma = prisma as any;
      mockPrisma.unitPlan.findMany.mockResolvedValue(mockUnitPlans);

      await runProgressCheck();

      // Verify that only Unit Plan A generates a warning (has future lessons)
      expect(mockWarn).toHaveBeenCalledWith(
        'Progress check notification: Unit Plan "Unit Plan A" is ending soon with 1 upcoming lessons'
      );
      expect(mockWarn).toHaveBeenCalledTimes(1);
    });

    it('should warn about multiple upcoming lessons', async () => {
      const today = new Date();
      const futureDate1 = new Date(today.getTime() + 86400000); // Tomorrow
      const futureDate2 = new Date(today.getTime() + 172800000); // Day after tomorrow

      const mockUnitPlans: TestUnitPlan[] = [
        {
          id: 'unit-plan-multi',
          title: 'Unit Plan with Multiple Lessons',
          endDate: futureDate2,
          startDate: today,
          userId: 1,
          createdAt: new Date(),
          updatedAt: new Date(),
          lessonPlans: [
            { id: 1, date: futureDate1, title: 'Tomorrow Lesson', unitPlanId: 'unit-plan-multi' },
            { id: 2, date: futureDate2, title: 'Day After Tomorrow', unitPlanId: 'unit-plan-multi' },
            { id: 3, date: new Date(today.getTime() - 86400000), title: 'Yesterday Lesson', unitPlanId: 'unit-plan-multi' }, // Past lesson
          ],
          user: { id: 1, name: 'Teacher 1' },
        },
      ];

      const mockPrisma = prisma as any;
      mockPrisma.unitPlan.findMany.mockResolvedValue(mockUnitPlans);

      await runProgressCheck();

      // Should report 2 upcoming lessons (both future dates)
      expect(mockWarn).toHaveBeenCalledWith(
        'Progress check notification: Unit Plan "Unit Plan with Multiple Lessons" is ending soon with 2 upcoming lessons'
      );
    });

    it('should not warn about unit plans with no upcoming lessons', async () => {
      const today = new Date();
      const pastDate = new Date(today.getTime() - 86400000); // Yesterday

      const mockUnitPlans: TestUnitPlan[] = [
        {
          id: 'unit-plan-completed',
          title: 'Completed Unit Plan',
          endDate: today,
          startDate: new Date(today.getTime() - 604800000), // Week ago
          userId: 1,
          createdAt: new Date(),
          updatedAt: new Date(),
          lessonPlans: [
            { id: 1, date: pastDate, title: 'Past Lesson', unitPlanId: 'unit-plan-completed' }, // Past lesson
          ],
          user: { id: 1, name: 'Teacher 1' },
        },
      ];

      const mockPrisma = prisma as any;
      mockPrisma.unitPlan.findMany.mockResolvedValue(mockUnitPlans);

      await runProgressCheck();

      // No warning should be generated for plans with only past lessons
      expect(mockWarn).not.toHaveBeenCalled();
    });

    it('should handle unit plans with no lesson plans', async () => {
      const today = new Date();
      const futureDate = new Date(today.getTime() + 86400000);

      const mockUnitPlans: TestUnitPlan[] = [
        {
          id: 'unit-plan-empty',
          title: 'Empty Unit Plan',
          endDate: futureDate,
          startDate: today,
          userId: 1,
          createdAt: new Date(),
          updatedAt: new Date(),
          lessonPlans: [], // No lessons
          user: { id: 1, name: 'Teacher 1' },
        },
      ];

      const mockPrisma = prisma as any;
      mockPrisma.unitPlan.findMany.mockResolvedValue(mockUnitPlans);

      await runProgressCheck();

      // No warning for unit plans without lessons
      expect(mockWarn).not.toHaveBeenCalled();
    });

    it('should handle empty result from database', async () => {
      const mockPrisma = prisma as any;
      mockPrisma.unitPlan.findMany.mockResolvedValue([]);

      await runProgressCheck();

      expect(mockWarn).not.toHaveBeenCalled();
    });

    it('should handle database errors gracefully', async () => {
      const mockPrisma = prisma as any;
      const dbError = new Error('Database connection failed');
      mockPrisma.unitPlan.findMany.mockRejectedValue(dbError);

      // The function should throw the error (no error handling in implementation)
      await expect(runProgressCheck()).rejects.toThrow('Database connection failed');
    });

    it('should correctly filter lessons by date boundary', async () => {
      const today = new Date();
      const todayMidnight = new Date(today);
      todayMidnight.setHours(0, 0, 0, 0);
      
      const todayEndOfDay = new Date(today);
      todayEndOfDay.setHours(23, 59, 59, 999);

      const mockUnitPlans: TestUnitPlan[] = [
        {
          id: 'unit-plan-boundary',
          title: 'Boundary Test Unit',
          endDate: new Date(today.getTime() + 86400000), // Tomorrow
          startDate: new Date(today.getTime() - 86400000), // Yesterday
          userId: 1,
          createdAt: new Date(),
          updatedAt: new Date(),
          lessonPlans: [
            { id: 1, date: new Date(today.getTime() - 1000), title: 'Just Before Now', unitPlanId: 'unit-plan-boundary' }, // Just before now
            { id: 2, date: today, title: 'Now', unitPlanId: 'unit-plan-boundary' }, // Exactly now (should not count as upcoming)
            { id: 3, date: new Date(today.getTime() + 1000), title: 'Just After Now', unitPlanId: 'unit-plan-boundary' }, // Just after now (should count)
          ],
          user: { id: 1, name: 'Teacher 1' },
        },
      ];

      const mockPrisma = prisma as any;
      mockPrisma.unitPlan.findMany.mockResolvedValue(mockUnitPlans);

      await runProgressCheck();

      // Should count only lessons that are strictly in the future (after current time)
      expect(mockWarn).toHaveBeenCalledWith(
        'Progress check notification: Unit Plan "Boundary Test Unit" is ending soon with 1 upcoming lessons'
      );
    });

    it('should verify job processes unit plans ending within next 7 days', async () => {
      const today = new Date();
      const in5Days = new Date(today.getTime() + 5 * 86400000); // 5 days from now
      const in10Days = new Date(today.getTime() + 10 * 86400000); // 10 days from now

      const mockUnitPlans: TestUnitPlan[] = [
        {
          id: 'unit-plan-within-week',
          title: 'Unit Within Week',
          endDate: in5Days,
          startDate: today,
          userId: 1,
          createdAt: new Date(),
          updatedAt: new Date(),
          lessonPlans: [
            { id: 1, date: in5Days, title: 'Future Lesson', unitPlanId: 'unit-plan-within-week' },
          ],
          user: { id: 1, name: 'Teacher 1' },
        },
        {
          id: 'unit-plan-beyond-week',
          title: 'Unit Beyond Week',
          endDate: in10Days,
          startDate: today,
          userId: 2,
          createdAt: new Date(),
          updatedAt: new Date(),
          lessonPlans: [
            { id: 2, date: in10Days, title: 'Far Future Lesson', unitPlanId: 'unit-plan-beyond-week' },
          ],
          user: { id: 2, name: 'Teacher 2' },
        },
      ];

      const mockPrisma = prisma as any;
      
      // Set up mock to capture the query
      mockPrisma.unitPlan.findMany.mockImplementation(async (query) => {
        // Only return unit plans that match the query criteria
        if (query?.where?.endDate?.lte) {
          const cutoffDate = query.where.endDate.lte;
          return mockUnitPlans.filter(plan => plan.endDate <= cutoffDate);
        }
        return mockUnitPlans;
      });

      await runProgressCheck();

      // Verify the query was made with correct date filter
      expect(mockPrisma.unitPlan.findMany).toHaveBeenCalledWith({
        where: {
          endDate: { lte: expect.any(Date) },
        },
        include: { lessonPlans: true, user: true },
      });

      // Only the unit plan within 7 days should generate a warning
      expect(mockWarn).toHaveBeenCalledWith(
        'Progress check notification: Unit Plan "Unit Within Week" is ending soon with 1 upcoming lessons'
      );
      expect(mockWarn).toHaveBeenCalledTimes(1);
    });

    it('should demonstrate notification system integration point', async () => {
      // This test documents the current implementation limitation
      // The code has a TODO comment about using ParentMessage or DaybookEntry
      // instead of the archived Notification model
      
      const today = new Date();
      const tomorrow = new Date(today.getTime() + 86400000);

      const mockUnitPlans: TestUnitPlan[] = [
        {
          id: 'unit-plan-notification',
          title: 'Test Notification Integration',
          endDate: tomorrow,
          startDate: today,
          userId: 1,
          createdAt: new Date(),
          updatedAt: new Date(),
          lessonPlans: [
            { id: 1, date: tomorrow, title: 'Future Lesson', unitPlanId: 'unit-plan-notification' },
          ],
          user: { id: 1, name: 'Teacher 1' },
        },
      ];

      const mockPrisma = prisma as any;
      mockPrisma.unitPlan.findMany.mockResolvedValue(mockUnitPlans);

      await runProgressCheck();

      // Currently only console.warn is used due to Notification model being archived
      expect(mockWarn).toHaveBeenCalledWith(
        'Progress check notification: Unit Plan "Test Notification Integration" is ending soon with 1 upcoming lessons'
      );
      
      // Future implementation should create ParentMessage or DaybookEntry records
      // This is documented in the code as a TODO
    });
  });
});